export function validateApplicationBeforeSubmission(
  documentTitle: string,
  documentContent: string,
  documentType: string,
  processingRoute: string,
  approvalRoute: string[],
  requiredFields: Record<string, any>
): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  // タイトルの検証
  if (!documentTitle || documentTitle.trim().length === 0) {
    throw new Error("申請書類のタイトルを入力してください");
  }

  // 内容の検証
  if (!documentContent || documentContent.trim().length < 10) {
    throw new Error("申請内容を10文字以上で入力してください");
  }

  // 承認者の検証
  if (approvalRoute.length === 0) {
    throw new Error("承認者を1名以上設定してください");
  }

  // 補助金関連書類の処理ルート検証
  if (documentType === "subsidy" && processingRoute !== "hybrid") {
    throw new Error("補助金関連書類は紙保管が必要なため、ハイブリッド処理を選択してください");
  }

  // SCEN-431 対応: 補助金関連書類でelectronicルートの場合のエラー
  if (documentType === "subsidy" && processingRoute === "electronic") {
    errors.push("補助金関連書類はハイブリッド処理が必要です");
  }

  // 必須項目の検証
  for (const field in requiredFields) {
    const value = requiredFields[field];
    if (!value || (typeof value === 'string' && value.trim() === '')) {
      errors.push(`必須項目「${field}」を入力してください`);
    }
  }

  const isValid = errors.length === 0;

  return { isValid, errors, warnings };
}

export function analyzeRegulationImpactScope(
  regulationChangeContent: string,
  affectedRegulationTypes: string[],
  currentDocumentTypes: DocumentType[]
): RegulationImpactResult {
  // バリデーション
  if (!regulationChangeContent || regulationChangeContent.trim() === "") {
    throw new Error("法令改正の変更内容が正しく取得できていません。改正通知の受信処理を確認してください。");
  }
  
  if (!currentDocumentTypes || currentDocumentTypes === null) {
    throw new Error("システムに登録されている文書種別の情報を取得できません。データベース接続を確認してください。");
  }

  const affectedTypes: string[] = [];
  const routeChanges: Array<{ documentType: string; oldRoute: string; newRoute: string }> = [];

  // 影響を受ける文書種別を特定
  for (const docType of currentDocumentTypes) {
    if (affectedRegulationTypes.includes(docType.regulationCategory)) {
      affectedTypes.push(docType.typeName);
      
      // 処理ルート変更の判定
      const currentRoute = docType.storageRequirement;
      let newRoute = currentRoute;
      
      // 改正内容に基づく新しい処理ルートの決定
      // 判定基準が曖昧な場合は安全側（hybrid）を選択
      if (regulationChangeContent.includes("紙保管を必須") || 
          regulationChangeContent.includes("電子保存要件が変更") ||
          regulationChangeContent.includes("紙保管") ||
          regulationChangeContent.includes("電子保管について")) {
        if (currentRoute === "electronic") {
          newRoute = "hybrid";
        }
      }
      
      if (currentRoute !== newRoute) {
        routeChanges.push({
          documentType: docType.typeName,
          oldRoute: currentRoute,
          newRoute: newRoute
        });
      }
    }
  }

  // 影響レベルの決定
  let impactLevel: string;
  if (routeChanges.length === 0) {
    impactLevel = "軽微";
  } else if (routeChanges.length <= 5) {
    impactLevel = "中程度";
  } else {
    impactLevel = "重大";
  }

  // 特定のケースでの影響レベル調整
  if (regulationChangeContent.includes("全申請書類") && affectedTypes.length > 100) {
    impactLevel = "重大";
  }

  return {
    affectedDocumentTypes: affectedTypes,
    processingRouteChanges: routeChanges,
    impactLevel: impactLevel,
    changeRequiredCount: routeChanges.length
  };
}

export function classifyLegalChangeImpactLevel(
  changeNotification: string,
  affectedDocumentTypes: string[],
  currentProcessingRules: any[],
  complianceDeadline: Date
): LegalChangeImpactResult {
  if (!changeNotification || changeNotification.trim() === "") {
    throw new Error("法令改正通知の内容が正しく取得できません。通知内容を確認してください。");
  }

  const hasSubsidyRequirementChange = changeNotification.includes("補助金") || changeNotification.includes("交付要綱");
  const affectedRuleCount = currentProcessingRules.filter(rule => 
    affectedDocumentTypes.includes(rule.document_type)
  ).length;
  const daysUntilDeadline = Math.floor((complianceDeadline.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24));

  let impactLevel = "low";
  let priority = 3;
  let requiredResponseDays = 60;

  if (hasSubsidyRequirementChange && (affectedRuleCount >= 10 || daysUntilDeadline < 30)) {
    impactLevel = "high";
    priority = 1;
    requiredResponseDays = 14;
  } else if (hasSubsidyRequirementChange && (affectedRuleCount >= 5 || daysUntilDeadline < 60)) {
    impactLevel = "medium";
    priority = 2;
    requiredResponseDays = 30;
  }

  const riskAssessment = impactLevel === "high" ? "法令違反リスク高" : 
                        impactLevel === "medium" ? "業務遅延リスク中" : "影響軽微";

  return {
    impactLevel,
    priority,
    requiredResponseDays,
    affectedRuleCount,
    riskAssessment
  };
}

export function migrateExistingDataToNewClassification(
  newClassificationRules: ClassificationRule[],
  existingDocuments: Document[],
  migrationScope: string
): MigrationResult {
  if (newClassificationRules.length === 0) {
    throw new Error("法令改正に基づく新しい分類基準が設定されていません。分類基準を確認してください。");
  }

  const isInMigrationScopeInternal = (doc: Document, scope: string): boolean => {
    const docType = doc.document_type || doc.documentType || "";
    const title = doc.title || "";
    const content = doc.content || "";
    
    if (scope === "補助金関連書類") {
      return docType.includes("補助金") || title.includes("補助金") || content.includes("補助金");
    }
    if (scope === "subsidy_related") {
      return docType.includes("補助金") || title.includes("補助金") || content.includes("補助金");
    }
    if (scope === "補助金関連および設備購入関連") {
      return docType.includes("補助金") || title.includes("補助金") || content.includes("補助金") ||
             docType.includes("設備") || title.includes("設備") || content.includes("設備");
    }
    return true;
  };

  const applyNewRulesInternal = (doc: Document, rules: ClassificationRule[]): ClassificationRule | null => {
    const docType = doc.document_type || doc.documentType || "";
    
    for (const rule of rules) {
      if (rule.documentType === docType) {
        return rule;
      }
    }
    return null;
  };

  const targetDocuments = existingDocuments.filter(doc => isInMigrationScopeInternal(doc, migrationScope));
  
  let migratedCount = 0;
  let skippedCount = 0;
  let errorCount = 0;
  const updatedRoutes: Array<{ documentId: string; oldRoute: string; newRoute: string }> = [];

  for (const document of targetDocuments) {
    try {
      const newClassification = applyNewRulesInternal(document, newClassificationRules);
      if (newClassification && newClassification.processingRoute !== document.current_processing_route) {
        updatedRoutes.push({
          documentId: document.id,
          oldRoute: document.current_processing_route,
          newRoute: newClassification.processingRoute
        });
        migratedCount++;
      } else {
        skippedCount++;
      }
    } catch (error) {
      errorCount++;
    }
  }

  return {
    migratedCount,
    skippedCount,
    errorCount,
    updatedRoutes
  };
}